```csharp
using System;
using System.Text;

class Program
{
    // XOR function for byte arrays
    static byte[] XorBytes(byte[] data, byte key)
    {
        byte[] result = new byte[data.Length];
        for(int i = 0; i < data.Length; i++)
        {
            result[i] = (byte)(data[i] ^ key);
        }
        return result;
    }

    static void Main()
    {
        // Step 1: Calculate pi up to 5 decimal places
        string piString = Math.PI.ToString("F5");
        Console.WriteLine("Pi (5 decimals): " + piString);

        // Convert string to bytes
        byte[] piBytes = Encoding.ASCII.GetBytes(piString);

        // Step 2: XOR with a key
        byte key = 0xAA; // Arbitrary XOR key
        byte[] xorOnce = XorBytes(piBytes, key);
        Console.WriteLine("After first XOR (byte values): " + BitConverter.ToString(xorOnce));

        // Step 3: XOR again with the same key to get original back
        byte[] xorTwice = XorBytes(xorOnce, key);
        string restoredString = Encoding.ASCII.GetString(xorTwice);
        Console.WriteLine("After second XOR (restored string): " + restoredString);
    }
}
