Certainly! Below is an example in C demonstrating a blocking `read()` on a file descriptor (like a pipe or a socket), which may be interrupted by a signal. The example shows how to properly handle the `EINTR` error by retrying the `read()`.

```c
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

ssize_t robust_read(int fd, void *buf, size_t count) {
    ssize_t n;

    while (1) {
        n = read(fd, buf, count);
        if (n < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, retry reading
                continue;
            } else {
                // Some other error
                perror("read");
                return -1;
            }
        }
        // read succeeded (n >= 0)
        return n;
    }
}

int main() {
    char buffer[100];
    ssize_t nbytes;

    printf("Please type something and hit enter:\n");

    nbytes = robust_read(STDIN_FILENO, buffer, sizeof(buffer) - 1);
    if (nbytes >= 0) {
        buffer[nbytes] = '\0'; // Null-terminate the string
        printf("Read %zd bytes: %s\n", nbytes, buffer);
    } else {
        printf("Read failed\n");
    }

    return 0;
}
```

### Explanation:
- `read()` is called inside a loop.
- If `read()` returns `-1` and `errno` is set to `EINTR`, it means the call was interrupted by a signal before any data was read.
- In that case, the loop continues and `read()` is retried.
- For any other error, the error is printed and the function returns `-1`.
- On success, `read()` returns the number of bytes read, which is then returned by `robust_read()`.

You can test this by running the program and sending a signal (e.g., pressing Ctrl+C which sends SIGINT) before typing input. The program will handle the interruption gracefully and continue waiting for input.

Certainly! Below is a simple example of a C++ program that creates a TCP server socket listening on port 888, accepts a connection, and reads network packets (data) from the connected client.

This example uses POSIX sockets, so it will work on Linux and similar Unix-like systems. For Windows, you would need to use Winsock with some modifications.

```cpp
#include <iostream>
#include <cstring>      // For memset
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h> // For sockaddr_in
#include <unistd.h>     // For close()

int main() {
    const int PORT = 888;
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    const int buffer_size = 1024;
    char buffer[buffer_size];

    // Create socket file descriptor (IPv4, TCP)
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        std::cerr << "Socket creation failed\n";
        return 1;
    }

    // Set SO_REUSEADDR to avoid "Address already in use" error on quick restarts
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        std::cerr << "setsockopt failed\n";
        close(server_fd);
        return 1;
    }

    // Bind the socket to the port 888
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        std::cerr << "Bind failed\n";
        close(server_fd);
        return 1;
    }

    // Listen for incoming connections (backlog = 3)
    if (listen(server_fd, 3) < 0) {
        std::cerr << "Listen failed\n";
        close(server_fd);
        return 1;
    }

    std::cout << "Waiting for connections on port " << PORT << "...\n";

    // Accept an incoming connection
    new_socket = accept(server_fd, (struct sockaddr*)&address, (socklen_t*)&addrlen);
    if (new_socket < 0) {
        std::cerr << "Accept failed\n";
        close(server_fd);
        return 1;
    }

    std::cout << "Connection accepted\n";

    // Read data from the socket
    ssize_t valread;
    while ((valread = read(new_socket, buffer, buffer_size - 1)) > 0) {
        buffer[valread] = '\0'; // Null-terminate the buffer to print as string
        std::cout << "Received: " << buffer << std::endl;
    }

    if (valread == 0) {
        std::cout << "Client disconnected\n";
    } else if (valread < 0) {
        std::cerr << "Read error\n";
    }

    // Close sockets
    close(new_socket);
    close(server_fd);

    return 0;
}
```

