```javascript
function elo(data) {
  if (data.length < 2) {
    throw new Error("At least two players are required");
  }

  // Find player with the minimum Matches
  let Player1 = data.reduce((minPlayer, player) => {
    return player.Matches < minPlayer.Matches ? player : minPlayer;
  }, data[0]);

  // Filter out Player1 from the list
  let others = data.filter(p => p !== Player1);

  // Select Player2 randomly from the rest
  let Player2 = others[Math.floor(Math.random() * others.length)];

  // Now you have Player1 as the player with the fewest matches,
