Certainly! Below is a simple example of GLSL shaders implementing old-school raycasting similar to the technique used in early 3D games like Wolfenstein 3D. This example assumes a 2D map and a simple first-person view with vertical strip rendering done in the fragment shader.

### Concept

- The vertex shader will render a fullscreen quad.
- The fragment shader will perform the raycasting for each vertical screen slice.
- The map is encoded as a uniform 2D array.
- The player position and direction are uniforms.
- The raycasting will be done per-pixel horizontally (x coordinate), with vertical slices corresponding to columns on screen.

---

## Vertex Shader (GLSL)

We render a fullscreen quad with a simple vertex shader that passes normalized screen coordinates to the fragment shader.

```glsl
#version 330 core

layout(location = 0) in vec2 aPosition; // Fullscreen quad positions [-1,1]

out vec2 vUV;

void main()
{
    vUV = (aPosition + 1.0) * 0.5; // Convert from [-1,1] to [0,1]
    gl_Position = vec4(aPosition, 0.0, 1.0);
}
```

---

## Fragment Shader (GLSL)

This shader performs the raycasting per-pixel horizontally. For simplicity, it assumes the map is a 2D integer array of size 24x24 (like in many tutorials). The ray is cast for each horizontal pixel coordinate.

```glsl
#version 330 core

in vec2 vUV;
out vec4 FragColor;

// Map dimensions
const int mapWidth = 24;
const int mapHeight = 24;

// 2D map: 0 = empty space, 1 = wall
uniform int uMap[mapWidth * mapHeight];

// Player data
uniform vec2 uPlayerPos;   // Player position in map units
uniform vec2 uPlayerDir;   // Player direction vector (normalized)
uniform vec2 uPlane;       // Camera plane, perpendicular to direction (controls FOV)

// Screen size
uniform vec2 uResolution;

float getMap(int x, int y)
{
    if (x < 0 || x >= mapWidth || y < 0 || y >= mapHeight)
        return 1; // Treat out of bounds as wall
    return float(uMap[y * mapWidth + x]);
}

void main()
{
    // Horizontal coordinate on screen [0..1]
    float x = vUV.x;

    // Calculate ray position and direction
    // CameraX ranges from -1 to 1 across the screen width
    float cameraX = 2.0 * x - 1.0;
    vec2 rayDir = uPlayerDir + uPlane * cameraX;

    // Which box of the map we're in
    int mapX = int(floor(uPlayerPos.x));
    int mapY = int(floor(uPlayerPos.y));

    // Length of ray from one x or y-side to next x or y-side
    float deltaDistX = (rayDir.x == 0.0) ? 1e30 : abs(1.0 / rayDir.x);
    float deltaDistY = (rayDir.y == 0.0) ? 1e30 : abs(1.0 / rayDir.y);

    // Calculate step and initial sideDist
    int stepX;
    int stepY;

    float sideDistX;
    float sideDistY;

    if(rayDir.x < 0.0)
    {
        stepX = -1;
        sideDistX = (uPlayerPos.x - float(mapX)) * deltaDistX;
    }
    else
    {
        stepX = 1;
        sideDistX = (float(mapX + 1) - uPlayerPos.x) * deltaDistX;
    }

    if(rayDir.y < 0.0)
    {
        stepY = -1;
        sideDistY = (uPlayerPos.y - float(mapY)) * deltaDistY;
    }
    else
    {
        stepY = 1;
        sideDistY = (float(mapY + 1) - uPlayerPos.y) * deltaDistY;
    }

    // Perform DDA
    int hit = 0; // Was a wall hit?
    int side;    // Was a NS or EW wall hit?

    while(hit == 0)
    {
        // Jump to next map square, either in x-direction or y-direction
        if(sideDistX < sideDistY)
        {
            sideDistX += deltaDistX;
            mapX += stepX;
            side = 0;
        }
        else
        {
            sideDistY += deltaDistY;
            mapY += stepY;
            side = 1;
        }

        // Check if ray has hit a wall
        if(getMap(mapX, mapY) > 0.0)
            hit = 1;
    }

    // Calculate distance projected on camera direction (Euclidean distance would give fisheye effect!)
    float perpWallDist;
    if(side == 0)
        perpWallDist = (float(mapX) - uPlayerPos.x + (1.0 - float(stepX)) / 2.0) / rayDir.x;
    else
        perpWallDist = (float(mapY) - uPlayerPos.y + (1.0 - float(stepY)) / 2.0) / rayDir.y;

    // Calculate height of line to draw on screen
    int lineHeight = int(uResolution.y / perpWallDist);

    // Calculate lowest and highest pixel to fill in current stripe
    int drawStart = int(-float(lineHeight) / 2.0 + uResolution.y / 2.0);
    int drawEnd = int(float(lineHeight) / 2.0 + uResolution.y / 2.0);

    // Current fragment y in pixels
    int yPixel = int(vUV.y * uResolution.y);

    vec3 color;

    if(yPixel < drawStart)
    {
        // Ceiling (simple color)
        color = vec3(0.5, 0.7, 1.0); // light blue ceiling
    }
    else if(yPixel > drawEnd)
    {
        // Floor (simple color)
        color = vec3(0.3, 0.3, 0.3); // dark grey floor
    }
    else
    {
        // Wall
        // Simple shading based on side
        float shade = (side == 1) ? 0.7 : 1.0;
        color = vec3(1.0, 0.0, 0.0) * shade; // red walls
    }

    FragColor = vec4(color, 1.0);
}
```

---

## Explanation & Usage Notes:

- **Vertex Shader**: Just draws a fullscreen quad, passing UVs from 0 to 1.
- **Fragment Shader**: Performs a single raycast per horizontal pixel coordinate.
- `uPlayerPos`, `uPlayerDir`, `uPlane` describe the player location, facing direction, and camera plane for the FOV.
- `uMap` is a flat integer array representing a 24x24 map.
- The fragment shader computes the vertical slice of the wall and colors ceiling, walls, and floor accordingly.
- This implementation is a minimal starting point and can be extended with textures, more complex shading, floor casting, etc.

---

