<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class CheckIpAddress
{
    /**
     * List of allowed IP addresses.
     *
     * @var array
     */
    protected $allowedIps = [
        '123.45.67.89',   // example IP 1
        '98.76.54.32',    // example IP 2
        // Add more IPs here
    ];

    /**
     * Handle an incoming request.
     *
     * @param  \Illuminate\Http\Request  $request
     * @param  \Closure(\Illuminate\Http\Request): (\Symfony\Component\HttpFoundation\Response)  $next
     * @return \Symfony\Component\HttpFoundation\Response
     */
    public function handle(Request $request, Closure $next): Response
    {
        if (!in_array($request->ip(), $this->allowedIps)) {
            abort(403, 'Unauthorized IP address.');
        }

        return $next($request);
    }
}
```

### Step 3: Register Middleware

To apply the middleware globally, add it in `app/Http/Kernel.php` in the `$middleware` array or to specific route groups or routes.

For example, to apply it to a route group:

```php
