Sure! I'll create a `FavoritesManager` class that handles adding/removing favorites either to the logged-in user's favorites (in DB) or to the session for guests. Then I'll create a `FavoritesController` that exposes API endpoints for adding/removing favorites and fetching the current favorites list.

---

### Assumptions
- You have a `Favorite` model that represents a favorite record in DB with at least:
  - `user_id` (foreign key to users)
  - `name` (string, the business name)
- You want to store favorites in session under a key like `'favorites'` as an array of names.
- The user is authenticated via Laravel's usual auth system.

---

### 1. FavoritesManager.php

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class FavoritesManager
{
    protected $request;
    protected $user;

    public function __construct(Request $request)
    {
        $this->request = $request;
        $this->user = Auth::user();
    }

    /**
     * Get the list of favorite names.
     *
     * @return array
     */
    public function getFavorites(): array
    {
        if ($this->user) {
            // Get all favorite names for the user from DB
            return $this->user->favorites()->pluck('name')->toArray();
        }

        // Guest - get from session
        return $this->request->session()->get('favorites', []);
    }

    /**
     * Add a name to favorites.
     *
     * @param string $name
     * @return bool True if added, false if already exists
     */
    public function add(string $name): bool
    {
        $name = trim($name);
        if ($name === '') {
            return false;
        }

        if ($this->user) {
            // Check if already in favorites
            $exists = $this->user->favorites()->where('name', $name)->exists();
            if ($exists) {
                return false;
            }

            // Add to DB
            $favorite = new Favorite();
            $favorite->user_id = $this->user->id;
            $favorite->name = $name;
            $favorite->save();

            return true;
        }

        // Guest - session
        $favorites = $this->request->session()->get('favorites', []);

        if (in_array($name, $favorites)) {
            return false;
        }

        $favorites[] = $name;

        $this->request->session()->put('favorites', $favorites);

        return true;
    }

    /**
     * Remove a name from favorites.
     *
     * @param string $name
     * @return bool True if removed, false if not found
     */
    public function remove(string $name): bool
    {
        $name = trim($name);
        if ($name === '') {
            return false;
        }

        if ($this->user) {
            $favorite = $this->user->favorites()->where('name', $name)->first();
            if (!$favorite) {
                return false;
            }

            $favorite->delete();
            return true;
        }

        // Guest - session
        $favorites = $this->request->session()->get('favorites', []);

        if (!in_array($name, $favorites)) {
            return false;
        }

        $favorites = array_filter($favorites, fn($fav) => $fav !== $name);

        $this->request->session()->put('favorites', array_values($favorites));

        return true;
    }
}
```

---

### 2. FavoritesController.php

```php
<?php

namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;

class FavoritesController extends Controller
{
    protected $favoritesManager;

    public function __construct(Request $request)
    {
        $this->favoritesManager = new FavoritesManager($request);
    }

    /**
     * Get all favorites.
     */
    public function index()
    {
        $favorites = $this->favoritesManager->getFavorites();

        return response()->json([
            'favorites' => $favorites,
        ]);
    }

    /**
     * Add a favorite.
     */
    public function store(Request $request)
    {
        $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $added = $this->favoritesManager->add($request->input('name'));

        if (!$added) {
            return response()->json([
                'message' => 'Name already in favorites or invalid.',
            ], 422);
        }

        return response()->json([
            'message' => 'Favorite added.',
            'favorites' => $this->favoritesManager->getFavorites(),
        ]);
    }

    /**
     * Remove a favorite.
     */
    public function destroy(Request $request, $name)
    {
        $name = trim($name);
        if ($name === '') {
            return response()->json(['message' => 'Invalid name.'], 422);
        }

        $removed = $this->favoritesManager->remove($name);

        if (!$removed) {
            return response()->json([
                'message' => 'Name not found in favorites.',
            ], 404);
        }

        return response()->json([
            'message' => 'Favorite removed.',
            'favorites' => $this->favoritesManager->getFavorites(),
        ]);
    }
}
```

---

### Notes:
- The controller expects routes like:
  - `GET /favorites` => `index`
  - `POST /favorites` => `store` (with JSON body `{ "name": "Business" }`)
  - `DELETE /favorites/{name}` => `destroy`
- You might want to URL-encode the name when calling the DELETE endpoint, as it is part of the URL.
- The `Favorite` model should have the inverse relation in `User` model:
```php
// In User.php model

public function favorites()
{
    return $this->hasMany(Favorite::class);
}
```
- Session favorites are just an array of strings.
- This setup cleanly handles both guest and logged-in users.

