Certainly! Below is an example of a Solidity smart contract implementing an ERC-1155 token with "creds" (credentials/credits) features. This contract uses OpenZeppelin's ERC1155 implementation and adds a simple "creds" system where each token ID can have associated "creds" that can be minted, transferred, or burned.

---

### Features:
- ERC-1155 multi-token standard
- "Creds" tracking per token ID per address
- Minting, burning, and transferring tokens
- Functions to get and modify creds for a token holder

---

### Prerequisites:
Make sure you have OpenZeppelin contracts installed:
```bash
npm install @openzeppelin/contracts
```

---

### Example Smart Contract

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract Creds1155 is ERC1155, Ownable {
    // Mapping from token ID => account => creds balance
    mapping(uint256 => mapping(address => uint256)) private _creds;

    // Token supply tracking (optional)
    mapping(uint256 => uint256) private _totalSupply;

    constructor(string memory uri_) ERC1155(uri_) {}

    /// @notice Mint tokens and assign creds for a specific token ID to an account
    function mint(address to, uint256 id, uint256 amount, uint256 credsAmount, bytes memory data) public onlyOwner {
        _mint(to, id, amount, data);
        _totalSupply[id] += amount;
        _creds[id][to] += credsAmount;
    }

    /// @notice Batch mint tokens and assign creds for multiple token IDs to an account
    function mintBatch(address to, uint256[] memory ids, uint256[] memory amounts, uint256[] memory credsAmounts, bytes memory data) public onlyOwner {
        require(ids.length == credsAmounts.length, "ids and credsAmounts length mismatch");
        _mintBatch(to, ids, amounts, data);
        for (uint256 i = 0; i < ids.length; i++) {
            _totalSupply[ids[i]] += amounts[i];
            _creds[ids[i]][to] += credsAmounts[i];
        }
    }

    /// @notice Burn tokens and reduce creds for a specific token ID from an account
    function burn(address from, uint256 id, uint256 amount, uint256 credsAmount) public {
        require(from == _msgSender() || isApprovedForAll(from, _msgSender()), "Not authorized to burn");
        _burn(from, id, amount);
        require(_creds[id][from] >= credsAmount, "Insufficient creds");
        _creds[id][from] -= credsAmount;
        _totalSupply[id] -= amount;
    }

    /// @notice Batch burn tokens and reduce creds for multiple token IDs from an account
    function burnBatch(address from, uint256[] memory ids, uint256[] memory amounts, uint256[] memory credsAmounts) public {
        require(ids.length == credsAmounts.length, "ids and credsAmounts length mismatch");
        require(from == _msgSender() || isApprovedForAll(from, _msgSender()), "Not authorized to burn");
        _burnBatch(from, ids, amounts);
        for (uint256 i = 0; i < ids.length; i++) {
            require(_creds[ids[i]][from] >= credsAmounts[i], "Insufficient creds");
            _creds[ids[i]][from] -= credsAmounts[i];
            _totalSupply[ids[i]] -= amounts[i];
        }
    }

    /// @notice Override safeTransferFrom to also transfer creds proportionally
    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes memory data) public virtual override {
        super.safeTransferFrom(from, to, id, amount, data);

        // Transfer creds proportionally
        uint256 fromCreds = _creds[id][from];
        require(fromCreds >= amount, "Insufficient creds to transfer");

        uint256 credsToTransfer = amount; // 1:1 creds to tokens transfer, adjust logic if needed
        _creds[id][from] -= credsToTransfer;
        _creds[id][to] += credsToTransfer;
    }

    /// @notice Override safeBatchTransferFrom to also transfer creds proportionally
    function safeBatchTransferFrom(address from, address to, uint256[] memory ids, uint256[] memory amounts, bytes memory data) public virtual override {
        super.safeBatchTransferFrom(from, to, ids, amounts, data);

        for (uint256 i = 0; i < ids.length; i++) {
            uint256 id = ids[i];
            uint256 amount = amounts[i];
            uint256 fromCreds = _creds[id][from];
            require(fromCreds >= amount, "Insufficient creds to transfer");

            uint256 credsToTransfer = amount; // 1:1 creds to tokens transfer
            _creds[id][from] -= credsToTransfer;
            _creds[id][to] += credsToTransfer;
        }
    }

    /// @notice Get creds balance of an account for a token ID
    function credsBalance(address account, uint256 id) public view returns (uint256) {
        return _creds[id][account];
    }

    /// @notice Get total supply for a token ID
    function totalSupply(uint256 id) public view returns (uint256) {
        return _totalSupply[id];
    }
}
```

---

### Notes:
- This implementation assumes creds are 1:1 with tokens transferred/minted/burned. You can customize the logic if creds represent different values.
- Only the contract owner can mint tokens.
- Creds are tracked per token ID and per account.
- When transferring tokens, the corresponding amount of creds are transferred as well.
- Burn functions remove both tokens and creds.
- You can extend this contract to add additional features like redeeming creds or special permissions.

---

If you'd like me to customize it further, such as adding specific credentials logic or integrating with other systems, just let me know!

Certainly! Here's a Tailscale ACL config that creates the three groups (`nill`, `family`, `servers`) and enforces the access rules you specified:

- `nill` group: full access to all servers on all ports.
- `family` group: can only use any servers as exit nodes (i.e., can route traffic through them) but cannot access services on any ports.
- `servers` group: access to port 22, 80, and 443 TCP on all servers, no other access.

---

```json
{
  "ACLs": [
    // nill group: full access to all servers on all ports
    {
      "Users": ["group:nill"],
      "Ports": ["group:servers:all"]
    },

    // family group: can only use servers as exit nodes, no direct service access
    // Deny direct access by not allowing any port access.
    // Exit node usage is controlled outside of ACLs by Tailscale flags,
    // but here we prevent direct connections by no Ports entries.

    // servers group: access to 22, 80, 443 TCP on all servers
    {
      "Users": ["group:servers"],
      "Ports": [
        "group:servers:22,80,443"
      ]
    }
  ],

  "Groups": {
    "nill": [
      "user1@example.com",
      "user2@example.com"
    ],
    "family": [
      "family1@example.com",
      "family2@example.com"
    ],
    "servers": [
      "server1@example.com",
      "server2@example.com"
    ]
  },

  "TagOwners": {
    "tag:server": ["group:servers"]
  },

  // Define the server nodes by tags, assuming all servers have tag "tag:server"
  // This allows defining "group:servers" in Ports.

  // Define the server group for Ports
  "Groups": {
    "servers": ["tag:server"]
  }
}
```

---

### Explanation:

- `Users` entries define users in each group. Replace `"user1@example.com"` etc. with real user emails.
- `Ports` entries control access permissions:
  - `"group:servers:all"` means all ports on all servers in the `servers` group.
  - `"group:servers:22,80,443"` means only TCP ports 22, 80, and 443 on servers.
- `family` group has no ACLs allowing direct port access; thus no direct connections are permitted. However, Tailscale exit-node use is controlled by client configuration (`--exit-node`), not by ACLs, so family users can select any server as an exit node if enabled on the server side.
- Servers are tagged with `"tag:server"`, which lets you reference them in ACLs.
- The `Groups` key is used twice in the example above. You should combine them properly.

---

### Corrected final config with combined Groups:

```json
{
  "ACLs": [
    {
      "Users": ["group:nill"],
      "Ports": ["group:servers:all"]
    },
    {
      "Users": ["group:servers"],
      "Ports": ["group:servers:22,80,443"]
    }
  ],

  "Groups": {
    "nill": [
      "user1@example.com",
      "user2@example.com"
    ],
    "family": [
      "family1@example.com",
      "family2@example.com"
    ],
    "servers": [
      "tag:server"
    ]
  },

  "TagOwners": {
    "tag:server": ["group:servers"]
  }
}
```

---

**Notes:**

- Replace user emails with actual users.
- Tag your server nodes with `tag:server` in Tailscale admin console or via CLI.
- Family users can only use exit nodes (assuming servers are enabled as exit nodes). They have no direct port access.
- Nill users have full access.
- Servers users have limited port access.

