## Frontend

### 1. Setup React app

In a separate folder:

```bash
npx create-react-app pern-todo-frontend
cd pern-todo-frontend
npm install axios
```

### 2. src/App.js

Replace the content of `src/App.js` with:

```jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [tasks, setTasks] = useState([]);
  const [description, setDescription] = useState('');

  const API_URL = 'http://localhost:5000/tasks';

  // Fetch all tasks
  const fetchTasks = async () => {
    try {
      const res = await axios.get(API_URL);
      setTasks(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  // Add new task
  const addTask = async (e) => {
    e.preventDefault();
    if (!description.trim()) return;
    try {
      const res = await axios.post(API_URL, { description });
      setTasks([res.data, ...tasks]);
      setDescription('');
    } catch (err) {
      console.error(err);
    }
  };

  // Toggle completed status
  const toggleCompleted = async (task) => {
    try {
      const res = await axios.put(`${API_URL}/${task.id}`, {
        completed: !task.completed,
      });
      setTasks(tasks.map(t => (t.id === task.id ? res.data : t)));
    } catch (err) {
      console.error(err);
    }
  };

  // Delete a task
  const deleteTask = async (id) => {
    try {
      await axios.delete(`${API_URL}/${id}`);
      setTasks(tasks.filter(t => t.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ maxWidth: 600, margin: '30px auto', fontFamily: 'Arial, sans-serif' }}>
      <h1>To-Do List (PERN Stack)</h1>
      <form onSubmit={addTask} style={{ marginBottom: 20 }}>
        <input
          type="text"
          placeholder="New task"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          style={{ padding: 10, width: '80%', fontSize: 16 }}
        />
        <button type="submit" style={{ padding: 10, fontSize: 16 }}>
          Add
        </button>
      </form>

      <ul style={{ listStyle: 'none', padding: 0 }}>
        {tasks.map((task) => (
          <li
            key={task.id}
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              padding: '10px 0',
              borderBottom: '1px solid #ccc',
              alignItems: 'center',
            }}
          >
            <div>
              <input
                type="checkbox"
                checked={task.completed}
                onChange={() => toggleCompleted(task)}
                style={{ marginRight: 10 }}
              />
              <span style={{ textDecoration: task.completed ? 'line-through' : 'none' }}>
                {task.description}
              </span>
            </div>
            <button
              onClick={() => deleteTask(task.id)}
              style={{
                background: 'red',
                color: 'white',
                border: 'none',
                padding: '5px 10px',
                cursor: 'pointer',
              }}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

### 3. Run the frontend

```bash
npm start
```

