- The activation function used is ReLU for the hidden layer.
- Softmax is not implemented here since in many hardware implementations, the softmax is either approximated or done off-chip.
- This code is designed to be synthesized with Vitis HLS and can be the basis for further optimization.

---

### Vitis HLS C++ code

```cpp
#include <ap_fixed.h>
#include <hls_stream.h>

#define INPUT_SIZE 784
#define HIDDEN_SIZE 128
#define OUTPUT_SIZE 10

// Fixed-point type: 16 bits total, 6 bits integer, 10 bits fraction
typedef ap_fixed<16,6> fixed_t;

// Activation function: ReLU
fixed_t relu(fixed_t x) {
#pragma HLS inline
    return (x > 0) ? x : 0;
}

// Fully connected layer
// input: input vector
// weights: weight matrix (rows x cols)
// biases: bias vector
// output: output vector
template<int input_dim, int output_dim>
void fully_connected(
    fixed_t input[input_dim],
    fixed_t weights[output_dim][input_dim],
    fixed_t biases[output_dim],
    fixed_t output[output_dim]
) {
#pragma HLS inline off

    FC_LOOP_OUT: for (int i = 0; i < output_dim; i++) {
#pragma HLS pipeline II=1
        fixed_t acc = biases[i];
        FC_LOOP_IN: for (int j = 0; j < input_dim; j++) {
#pragma HLS unroll factor=4
            acc += weights[i][j] * input[j];
        }
        output[i] = acc;
    }
}

// Top function for Vitis HLS
// input_image: input grayscale image, values normalized between 0 and 1
// weights1, biases1: weights and biases for first layer
// weights2, biases2: weights and biases for output layer
// output_scores: final output scores (logits) for 10 classes
extern "C" {
void mnist_mlp(
    fixed_t input_image[INPUT_SIZE],
    fixed_t weights1[HIDDEN_SIZE][INPUT_SIZE],
    fixed_t biases1[HIDDEN_SIZE],
    fixed_t weights2[OUTPUT_SIZE][HIDDEN_SIZE],
    fixed_t biases2[OUTPUT_SIZE],
    fixed_t output_scores[OUTPUT_SIZE]
) {
#pragma HLS INTERFACE m_axi port=input_image offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=weights1 offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=biases1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=weights2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=biases2 offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=output_scores offset=slave bundle=gmem5

#pragma HLS INTERFACE s_axilite port=input_image bundle=control
#pragma HLS INTERFACE s_axilite port=weights1 bundle=control
#pragma HLS INTERFACE s_axilite port=biases1 bundle=control
#pragma HLS INTERFACE s_axilite port=weights2 bundle=control
#pragma HLS INTERFACE s_axilite port=biases2 bundle=control
#pragma HLS INTERFACE s_axilite port=output_scores bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    fixed_t hidden_layer[HIDDEN_SIZE];
#pragma HLS array_partition variable=hidden_layer cyclic factor=8

    // Fully connected layer 1 + ReLU
    fully_connected<INPUT_SIZE, HIDDEN_SIZE>(input_image, weights1, biases1, hidden_layer);

    FC1_RELU_LOOP: for (int i = 0; i < HIDDEN_SIZE; i++) {
#pragma HLS unroll factor=8
        hidden_layer[i] = relu(hidden_layer[i]);
    }

    // Fully connected layer 2 (output layer)
    fully_connected<HIDDEN_SIZE, OUTPUT_SIZE>(hidden_layer, weights2, biases2, output_scores);
}
}
```

---

### How to use this

- Pre-train your MNIST MLP network in Python or any other framework.
- Extract and quantize weights/biases to the fixed-point format.
- Load weights and biases into arrays passed to the kernel.
- Normalize the input image pixels to `[0,1]` floating point and then convert to `fixed_t`.
- Run the kernel in Vitis HLS environment to generate FPGA IP.
- Integrate with your FPGA application.

---

