Creating a simple sprite editor in JavaScript involves building a small web app where you can draw pixels on a grid and then export the sprite data. Below is a complete example that implements a basic sprite editor with the following features:

- A pixel grid where you can click to toggle pixels on/off
- Ability to change the color used for drawing
- Clear the canvas
- Export the sprite data as a JSON array or image

---

### Complete Sprite Editor Code

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Simple Sprite Editor</title>
<style>
  body {
    font-family: Arial, sans-serif;
    padding: 20px;
    background: #222;
    color: #eee;
    display: flex;
    flex-direction: column;
    align-items: center;
  }
  #spriteCanvas {
    border: 1px solid #555;
    image-rendering: pixelated;
    cursor: crosshair;
    background: #111;
  }
  .controls {
    margin-top: 10px;
    display: flex;
    gap: 10px;
    align-items: center;
  }
  button, select {
    padding: 6px 12px;
    font-size: 16px;
  }
  textarea {
    margin-top: 20px;
    width: 320px;
    height: 150px;
    background: #333;
    color: #eee;
    border: none;
    padding: 10px;
    font-family: monospace;
    font-size: 14px;
    resize: none;
  }
</style>
</head>
<body>

<h1>Simple Sprite Editor</h1>

<canvas id="spriteCanvas" width="320" height="320"></canvas>

<div class="controls">
  <label for="colorPicker">Color:</label>
  <input type="color" id="colorPicker" value="#ffffff" />

  <button id="clearBtn">Clear</button>
  <button id="exportJsonBtn">Export JSON</button>
  <button id="exportPngBtn">Export PNG</button>
</div>

<textarea id="output" placeholder="Exported data will appear here..." readonly></textarea>

<script>
(() => {
  const canvas = document.getElementById('spriteCanvas');
  const ctx = canvas.getContext('2d');

  // Sprite grid size
  const gridWidth = 32;
  const gridHeight = 32;
  const pixelSize = canvas.width / gridWidth;

  // Data structure: 2D array storing color or null for transparent
  const spriteData = [];
  for(let y = 0; y < gridHeight; y++) {
    spriteData[y] = new Array(gridWidth).fill(null);
  }

  let currentColor = '#ffffff';
  const colorPicker = document.getElementById('colorPicker');
  const clearBtn = document.getElementById('clearBtn');
  const exportJsonBtn = document.getElementById('exportJsonBtn');
  const exportPngBtn = document.getElementById('exportPngBtn');
  const output = document.getElementById('output');

  let isDrawing = false;

  function drawGrid() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw pixels
    for(let y = 0; y < gridHeight; y++) {
      for(let x = 0; x < gridWidth; x++) {
        const color = spriteData[y][x];
        if(color) {
          ctx.fillStyle = color;
          ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
        }
      }
    }

    // Draw grid lines
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 1;
    for(let i = 0; i <= gridWidth; i++) {
      ctx.beginPath();
      ctx.moveTo(i * pixelSize, 0);
      ctx.lineTo(i * pixelSize, canvas.height);
      ctx.stroke();
    }
    for(let i = 0; i <= gridHeight; i++) {
      ctx.beginPath();
      ctx.moveTo(0, i * pixelSize);
      ctx.lineTo(canvas.width, i * pixelSize);
      ctx.stroke();
    }
  }

  function getMousePos(evt) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const x = Math.floor((evt.clientX - rect.left) * scaleX / pixelSize);
    const y = Math.floor((evt.clientY - rect.top) * scaleY / pixelSize);

    if(x < 0 || x >= gridWidth || y < 0 || y >= gridHeight) return null;
    return {x, y};
  }

  function togglePixel(x, y) {
    if(spriteData[y][x] === currentColor) {
      // Turn off the pixel if it has the same color
      spriteData[y][x] = null;
    } else {
      spriteData[y][x] = currentColor;
    }
  }

  canvas.addEventListener('mousedown', (evt) => {
    const pos = getMousePos(evt);
    if(pos) {
      togglePixel(pos.x, pos.y);
      drawGrid();
      isDrawing = true;
    }
  });

  canvas.addEventListener('mousemove', (evt) => {
    if(!isDrawing) return;
    const pos = getMousePos(evt);
    if(pos) {
      // Set pixel to current color (no toggle on drag)
      if(spriteData[pos.y][pos.x] !== currentColor) {
        spriteData[pos.y][pos.x] = currentColor;
        drawGrid();
      }
    }
  });

  canvas.addEventListener('mouseup', () => {
    isDrawing = false;
  });
  canvas.addEventListener('mouseleave', () => {
    isDrawing = false;
  });

  colorPicker.addEventListener('input', (evt) => {
    currentColor = evt.target.value;
  });

  clearBtn.addEventListener('click', () => {
    for(let y = 0; y < gridHeight; y++) {
      spriteData[y].fill(null);
    }
    output.value = '';
    drawGrid();
  });

  exportJsonBtn.addEventListener('click', () => {
    // Export spriteData as JSON with colors or null
    output.value = JSON.stringify(spriteData);
  });

  exportPngBtn.addEventListener('click', () => {
    // Create a temporary offscreen canvas at sprite size (32x32)
    const exportCanvas = document.createElement('canvas');
    exportCanvas.width = gridWidth;
    exportCanvas.height = gridHeight;
    const exportCtx = exportCanvas.getContext('2d');

    // Draw pixels scaled to 1:1 to get pixel art image
    for(let y = 0; y < gridHeight; y++) {
      for(let x = 0; x < gridWidth; x++) {
        const color = spriteData[y][x];
        if(color) {
          exportCtx.fillStyle = color;
          exportCtx.fillRect(x, y, 1, 1);
        }
      }
    }

    // Convert to data URL and show in output box
    const dataUrl = exportCanvas.toDataURL('image/png');
    output.value = dataUrl;

    // Optionally, trigger a download
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = 'sprite.png';
    link.click();
  });

  drawGrid();
})();
</script>

</body>
</html>
```

---

### How it works:

- The editor provides a 32x32 pixel grid.
- Clicking a pixel toggles it on/off using the selected color.
- You can click and drag to paint pixels.
- The color picker changes the current drawing color.
- "Clear" resets the sprite.
- "Export JSON" outputs the 2D array of colors (or null for transparent).
- "Export PNG" generates a 32x32 PNG image and prompts a download.

---

### How to use:

1. Save the above code into an `.html` file.
2. Open it in your browser.
3. Draw your sprite pixel by pixel.
4. Export your sprite as JSON or PNG.

