Certainly! Below is a JavaScript function that takes a JSON object (parsed from a JSON file) and an entity key to search for. It recursively searches through all nested objects (maps) and collects the values along with their "location" (path) in the JSON structure.

```javascript
/**
 * Recursively searches for all occurrences of a key in a nested JSON object.
 *
 * @param {Object} jsonObj - The JSON object to search.
 * @param {string} entityKey - The key to search for.
 * @returns {Array} - An array of objects with `value` and `location` (path as an array of keys).
 */
function findEntityKey(jsonObj, entityKey) {
  const results = [];

  /**
   * Helper recursive function to traverse the JSON object.
   *
   * @param {Object} obj - current object or value
   * @param {Array} path - array representing the path to the current obj
   */
  function recurse(obj, path) {
    if (obj !== null && typeof obj === 'object') {
      if (Array.isArray(obj)) {
        // If obj is an array, iterate over elements with their indices
        obj.forEach((item, index) => {
          recurse(item, path.concat([index]));
        });
      } else {
        // obj is a non-array object
        for (const key in obj) {
          if (obj.hasOwnProperty(key)) {
            if (key === entityKey) {
              results.push({
                value: obj[key],
                location: path.concat([key])
              });
            }
            recurse(obj[key], path.concat([key]));
          }
        }
      }
    }
  }

  recurse(jsonObj, []);
  return results;
}
```

### Usage example:

Suppose you have the following JSON object:

```javascript
const data = {
  "user": {
    "id": 1,
    "name": "Alice",
    "details": {
      "email": "alice@example.com",
      "preferences": {
        "theme": "dark"
      }
    }
  },
  "posts": [
    {
      "id": 101,
      "title": "First Post",
      "author": {
        "id": 1,
        "name": "Alice"
      }
    },
    {
      "id": 102,
      "title": "Second Post",
      "author": {
        "id": 2,
        "name": "Bob"
      }
    }
  ]
};
```

If you want to find all `id` keys:

```javascript
const foundIds = findEntityKey(data, 'id');
console.log(foundIds);
```

Output:

```javascript
[
  { value: 1, location: ['user', 'id'] },
  { value: 101, location: ['posts', 0, 'id'] },
  { value: 1, location: ['posts', 0, 'author', 'id'] },
  { value: 102, location: ['posts', 1, 'id'] },
  { value: 2, location: ['posts', 1, 'author', 'id'] }
]
```

---

### Notes:
- The `location` is an array representing the path of keys and indices to reach the entity key.
- The function handles nested objects and arrays.
- You can easily adapt or extend this to handle other JSON structures or output formats.

