Sure! Here's a simple Python program to play Connect-4 in the console. It supports two human players taking turns dropping pieces into a 7-column, 6-row board. The program checks for wins and draws after each move.

```python
ROWS = 6
COLS = 7

def create_board():
    return [[' ' for _ in range(COLS)] for _ in range(ROWS)]

def print_board(board):
    print()
    for row in board:
        print('| ' + ' | '.join(row) + ' |')
    print('  ' + '   '.join(str(i) for i in range(COLS)))
    print()

def is_valid_location(board, col):
    return board[0][col] == ' '

def get_next_open_row(board, col):
    for r in range(ROWS-1, -1, -1):
        if board[r][col] == ' ':
            return r
    return None

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(COLS - 3):
        for r in range(ROWS):
            if (board[r][c] == piece and
                board[r][c+1] == piece and
                board[r][c+2] == piece and
                board[r][c+3] == piece):
                return True

    # Check vertical locations for win
    for c in range(COLS):
        for r in range(ROWS - 3):
            if (board[r][c] == piece and
                board[r+1][c] == piece and
                board[r+2][c] == piece and
                board[r+3][c] == piece):
                return True

    # Check positively sloped diagonals
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if (board[r][c] == piece and
                board[r+1][c+1] == piece and
                board[r+2][c+2] == piece and
                board[r+3][c+3] == piece):
                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if (board[r][c] == piece and
                board[r-1][c+1] == piece and
                board[r-2][c+2] == piece and
                board[r-3][c+3] == piece):
                return True

    return False

def is_board_full(board):
    for c in range(COLS):
        if is_valid_location(board, c):
            return False
    return True

def play_connect4():
    board = create_board()
    game_over = False
    turn = 0  # Player 1 starts ('X'), Player 2 is 'O'

    print("Welcome to Connect 4!")
    print_board(board)

    while not game_over:
        if turn == 0:
            piece = 'X'
            player = 1
        else:
            piece = 'O'
            player = 2

        # Ask for player input
        try:
            col = int(input(f"Player {player} ({piece}), choose a column (0-{COLS-1}): "))
        except ValueError:
            print("Invalid input. Please enter an integer.")
            continue

        if col < 0 or col >= COLS:
            print(f"Column must be between 0 and {COLS-1}. Try again.")
            continue

        if not is_valid_location(board, col):
            print("Column is full. Try another one.")
            continue

        row = get_next_open_row(board, col)
        drop_piece(board, row, col, piece)
        print_board(board)

        if winning_move(board, piece):
            print(f"Player {player} ({piece}) wins! Congratulations!")
            game_over = True
        elif is_board_full(board):
            print("The board is full. It's a draw!")
            game_over = True
        else:
            turn = (turn + 1) % 2

if __name__ == "__main__":
    play_connect4()
```

### How to run
- Save this code to a file, for example `connect4.py`.
- Run it with Python 3: `python connect4.py`
- Players take turns entering the column number (0 to 6) where they want to drop their piece.

