### `MessagesViewController.swift`

```swift
import UIKit
import Messages

class MessagesViewController: MSMessagesAppViewController {

    // Two buttons to display
    private let button1: UIButton = {
        let button = UIButton(type: .system)
        button.setTitle("Button 1", for: .normal)
        button.translatesAutoresizingMaskIntoConstraints = false
        return button
    }()

    private let button2: UIButton = {
        let button = UIButton(type: .system)
        button.setTitle("Button 2", for: .normal)
        button.translatesAutoresizingMaskIntoConstraints = false
        return button
    }()

    override func viewDidLoad() {
        super.viewDidLoad()

        // Add buttons to the view
        view.addSubview(button1)
        view.addSubview(button2)

        // Add targets for buttons
        button1.addTarget(self, action: #selector(button1Tapped), for: .touchUpInside)
        button2.addTarget(self, action: #selector(button2Tapped), for: .touchUpInside)

        setupConstraints()
    }

    private func setupConstraints() {
        // Layout buttons side by side with some spacing
        NSLayoutConstraint.activate([
            // Button 1 constraints
            button1.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 20),
            button1.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            button1.heightAnchor.constraint(equalToConstant: 44),

            // Button 2 constraints
            button2.leadingAnchor.constraint(equalTo: button1.trailingAnchor, constant: 20),
            button2.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            button2.heightAnchor.constraint(equalToConstant: 44),
            button2.trailingAnchor.constraint(lessThanOrEqualTo: view.trailingAnchor, constant: -20)
        ])
    }

    @objc private func button1Tapped() {
        // Example: Insert a message when Button 1 is tapped
        insertMessage(text: "Button 1 tapped!")
    }

    @objc private func button2Tapped() {
        // Example: Insert a message when Button 2 is tapped
        insertMessage(text: "Button 2 tapped!")
    }

    private func insertMessage(text: String) {
        guard let conversation = activeConversation else { return }

        let layout = MSMessageTemplateLayout()
        layout.caption = text

        let message = MSMessage()
        message.layout = layout

        conversation.insert(message) { error in
            if let error = error {
                print("Error inserting message: \(error)")
            }
        }
    }

    // Optional: Handle presentation style changes if needed
    override func willTransition(to presentationStyle: MSMessagesAppPresentationStyle) {
        super.willTransition(to: presentationStyle)
        // You can adjust the UI if you want to support expanded presentation style
    }
}
```

