```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

class Program
{
    static List<string> ExtractHashtags(string text)
    {
        var hashtags = new List<string>();
        // Regex pattern to match hashtags: # followed by one or more word characters (letters, digits, underscore)
        var matches = Regex.Matches(text, @"#\w+");

        foreach (Match match in matches)
        {
            hashtags.Add(match.Value);
        }

        return hashtags;
    }

    static void Main(string[] args)
    {
        string input = "Here are some hashtags: #CSharp #dotnet #100DaysOfCode! Let's extract #hashtags.";

        List<string> extractedHashtags = ExtractHashtags(input);

        Console.WriteLine("Extracted hashtags:");
        foreach (string hashtag in extractedHashtags)
        {
            Console.WriteLine(hashtag);
        }
    }
}
```

### Explanation:
- The regex pattern `#\w+` looks for the `#` symbol followed by one or more word characters (`\w` includes letters, digits, and underscore).
- The `Regex.Matches` method returns all matches in the input text.
- Each matched hashtag is added to a list and then printed out.

